#!/usr/bin/env python3
"""Amazon Product Catalog Performance & Customer Sentiment Analysis Report Generator."""

import pandas as pd
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import matplotlib.ticker as mticker
from matplotlib.gridspec import GridSpec
import seaborn as sns
from io import BytesIO
import base64
import json
import re
import os
from collections import Counter

# ── Configuration ──────────────────────────────────────────────────────────
plt.rcParams.update({
    'font.size': 11,
    'axes.titlesize': 14,
    'axes.labelsize': 11,
    'figure.dpi': 120,
    'savefig.bbox': 'tight',
    'savefig.pad_inches': 0.1,
})
sns.set_style("whitegrid")
OUTPUT_PATH = '/app/output/final_report.html'
DATA_PATH = '/app/benchmark/data.csv'

# ── Color palette ──────────────────────────────────────────────────────────
C_PRIMARY   = '#1a73e8'  # blue
C_SECONDARY = '#0d904f'  # green
C_ACCENT    = '#e8710a'  # orange
C_DARK      = '#202124'
C_LIGHT     = '#5f6368'
C_BG        = '#f8f9fa'
C_WHITE     = '#ffffff'
C_RED       = '#d93025'
CARD_COLORS = ['#1a73e8', '#0d904f', '#e8710a', '#9334e6']

# ── Data Loading & Cleaning ────────────────────────────────────────────────
print("Loading data...")
df = pd.read_csv(DATA_PATH, encoding='utf-8-sig')
print(f"  {len(df):,} rows loaded")

def clean_price(val):
    """Clean price strings like '₹399' or '₹1,099' to float."""
    if pd.isna(val):
        return np.nan
    s = str(val).replace('₹', '').replace(',', '').strip()
    try:
        return float(s)
    except ValueError:
        return np.nan

def clean_pct(val):
    """Clean percentage strings like '64%' to float."""
    if pd.isna(val):
        return np.nan
    try:
        return float(str(val).replace('%', '').strip())
    except ValueError:
        return np.nan

def clean_rating(val):
    """Clean rating - handle pipe-separated malformed values."""
    if pd.isna(val):
        return np.nan
    s = str(val).strip()
    if '|' in s:
        parts = [float(p) for p in re.split(r'\|+', s) if p.strip()]
        return np.mean(parts) if parts else np.nan
    try:
        return float(s)
    except ValueError:
        return np.nan

def clean_int(val):
    """Clean integer strings with commas like '24,269'."""
    if pd.isna(val):
        return np.nan
    s = str(val).replace(',', '').strip()
    try:
        return int(s)
    except ValueError:
        return np.nan

print("Cleaning data...")
df['discounted_price_num'] = df['discounted_price'].apply(clean_price)
df['actual_price_num']     = df['actual_price'].apply(clean_price)
df['discount_pct_num']     = df['discount_percentage'].apply(clean_pct)
df['rating_num']           = df['rating'].apply(clean_rating)
df['rating_count_num']     = df['rating_count'].apply(clean_int)

# Compute savings amount
df['savings_amount'] = df['actual_price_num'] - df['discounted_price_num']
df['savings_pct_check'] = (df['savings_amount'] / df['actual_price_num'] * 100)

# Extract top-level category
def top_category(cat):
    if pd.isna(cat):
        return 'Unknown'
    return str(cat).split('|')[0].strip()

df['top_category'] = df['category'].apply(top_category)

# Extract sub-category (second level)
def sub_category(cat):
    if pd.isna(cat):
        return 'Unknown'
    parts = str(cat).split('|')
    if len(parts) >= 2:
        return parts[1].strip()
    return parts[0].strip()

df['sub_category'] = df['category'].apply(sub_category)

# Filter to valid ratings
df_valid = df[df['rating_num'].notna() & (df['rating_num'] >= 1) & (df['rating_num'] <= 5)].copy()
print(f"  Valid products (with rating): {len(df_valid):,}")

# ── KPI Computation ────────────────────────────────────────────────────────
print("Computing KPIs...")
# Use all products where possible, valid-rating products for rating KPIs
avg_rating        = df_valid['rating_num'].mean()
avg_discount      = df['discount_pct_num'].mean()
median_rating_cnt = df['rating_count_num'].median()
high_rating_pct   = (df_valid['rating_num'] >= 4.0).mean() * 100
total_products    = len(df)

# Correlation: discount vs rating
corr_df = df_valid.dropna(subset=['discount_pct_num', 'rating_num'])
discount_rating_corr = corr_df['discount_pct_num'].corr(corr_df['rating_num'])

# Correlation: discount vs rating count
corr2_df = df_valid.dropna(subset=['discount_pct_num', 'rating_count_num'])
discount_rct_corr = corr2_df['discount_pct_num'].corr(corr2_df['rating_count_num'])

# Correlation: price vs rating
corr3_df = df_valid.dropna(subset=['actual_price_num', 'rating_num'])
price_rating_corr = corr3_df['actual_price_num'].corr(corr3_df['rating_num'])

kpi_values = {
    'avg_rating': avg_rating,
    'avg_discount': avg_discount,
    'median_rating_count': median_rating_cnt,
    'high_rating_pct': high_rating_pct,
    'total_products': total_products,
    'discount_rating_corr': discount_rating_corr,
    'discount_rct_corr': discount_rct_corr,
    'price_rating_corr': price_rating_corr,
}
print(f"  Avg Rating: {avg_rating:.2f} | Avg Discount: {avg_discount:.2f}% | High Rating: {high_rating_pct:.1f}%")
print(f"  Discount-Rating Corr: {discount_rating_corr:.4f} | Discount-Reviews Corr: {discount_rct_corr:.4f}")

# ── Chart: fig_to_b64 helper ───────────────────────────────────────────────
def fig_to_b64(fig):
    buf = BytesIO()
    fig.savefig(buf, format='png', dpi=150, bbox_inches='tight', facecolor=C_WHITE, edgecolor='none')
    buf.seek(0)
    b64 = base64.b64encode(buf.read()).decode()
    plt.close(fig)
    return b64

# ── Generate all charts ────────────────────────────────────────────────────
print("Generating charts...")

# Chart 1: Rating Distribution Histogram
fig1, ax1 = plt.subplots(figsize=(8, 4.5))
bins = np.arange(0.5, 5.51, 0.25)
ax1.hist(df_valid['rating_num'].dropna(), bins=bins, color=C_PRIMARY, edgecolor='white', alpha=0.9)
ax1.axvline(avg_rating, color=C_ACCENT, linestyle='--', linewidth=2, label=f'Mean: {avg_rating:.2f}')
ax1.set_title('Distribution of Product Ratings', fontweight='bold')
ax1.set_xlabel('Rating (1–5)')
ax1.set_ylabel('Number of Products')
ax1.legend()
chart_rating_dist = fig_to_b64(fig1)

# Chart 2: Top Categories by Count & Avg Rating
top_cats = df_valid.groupby('top_category').agg(
    count=('rating_num', 'count'),
    avg_rating=('rating_num', 'mean'),
    avg_discount=('discount_pct_num', 'mean'),
    avg_rating_count=('rating_count_num', 'mean'),
    median_price=('discounted_price_num', 'median')
).reset_index()
top_cats = top_cats.sort_values('count', ascending=False).head(12)

fig2, ax2 = plt.subplots(figsize=(10, 5.5))
bars = ax2.barh(top_cats['top_category'], top_cats['avg_rating'], color=C_PRIMARY, alpha=0.85, height=0.6)
for i, (bar, val) in enumerate(zip(bars, top_cats['avg_rating'])):
    ax2.text(val + 0.02, bar.get_y() + bar.get_height()/2, f'{val:.2f}',
             va='center', fontsize=9, color=C_DARK)
ax2.set_title('Average Rating by Product Category (Top 12 by Volume)', fontweight='bold')
ax2.set_xlabel('Average Rating')
ax2.set_xlim(3.0, 5.0)
ax2.invert_yaxis()
chart_cat_rating = fig_to_b64(fig2)

# Chart 3: Category table data (sorted for ranking)
cat_table_data = top_cats[['top_category', 'count', 'avg_rating', 'avg_discount', 'avg_rating_count']].copy()
cat_table_data.columns = ['Category', 'Products', 'Avg Rating', 'Avg Discount %', 'Avg Review Count']
cat_table_data['Avg Rating'] = cat_table_data['Avg Rating'].round(2)
cat_table_data['Avg Discount %'] = cat_table_data['Avg Discount %'].round(1)
cat_table_data['Avg Review Count'] = cat_table_data['Avg Review Count'].round(0).astype(int)

# Chart 4: Discount vs Rating Scatter with trend line
fig4, ax4 = plt.subplots(figsize=(8, 5.5))
sample = corr_df.sample(min(800, len(corr_df)), random_state=42)
ax4.scatter(sample['discount_pct_num'], sample['rating_num'], alpha=0.35, s=20,
            c=C_PRIMARY, edgecolors='none')
z = np.polyfit(corr_df['discount_pct_num'], corr_df['rating_num'], 1)
p = np.poly1d(z)
x_line = np.linspace(0, 100, 100)
ax4.plot(x_line, p(x_line), color=C_ACCENT, linewidth=2, linestyle='--',
         label=f'Trend (r={discount_rating_corr:.3f})')
ax4.set_title('Discount Percentage vs Customer Rating', fontweight='bold')
ax4.set_xlabel('Discount Percentage (%)')
ax4.set_ylabel('Rating')
ax4.legend()
chart_discount_vs_rating = fig_to_b64(fig4)

# Chart 5: Price vs Rating scatter
fig5, ax5 = plt.subplots(figsize=(8, 5.5))
price_sample = corr3_df[corr3_df['actual_price_num'] < corr3_df['actual_price_num'].quantile(0.95)]
ax5.scatter(price_sample['actual_price_num'], price_sample['rating_num'], alpha=0.35, s=20,
            c=C_SECONDARY, edgecolors='none')
z5 = np.polyfit(price_sample['actual_price_num'].dropna(), price_sample['rating_num'].dropna(), 1)
p5 = np.poly1d(z5)
x5 = np.linspace(price_sample['actual_price_num'].min(), price_sample['actual_price_num'].max(), 100)
ax5.plot(x5, p5(x5), color=C_ACCENT, linewidth=2, linestyle='--', label=f'Trend (r={price_rating_corr:.3f})')
ax5.set_title('Actual Price vs Customer Rating', fontweight='bold')
ax5.set_xlabel('Actual Price (INR)')
ax5.set_ylabel('Rating')
ax5.legend()
chart_price_vs_rating = fig_to_b64(fig5)

# Chart 6: Discount Bracket Analysis
df_valid['discount_bracket'] = pd.cut(df_valid['discount_pct_num'],
    bins=[0, 20, 40, 60, 80, 100], labels=['0-20%', '20-40%', '40-60%', '60-80%', '80-100%'])
bracket_stats = df_valid.groupby('discount_bracket', observed=True).agg(
    count=('rating_num', 'count'),
    avg_rating=('rating_num', 'mean'),
    avg_rating_count=('rating_count_num', 'mean')
).reset_index().dropna()

fig6, ax6a = plt.subplots(figsize=(9, 5))
x_pos = np.arange(len(bracket_stats))
width = 0.35
bars1 = ax6a.bar(x_pos - width/2, bracket_stats['avg_rating'], width, color=C_PRIMARY,
                  alpha=0.85, label='Avg Rating')
ax6a.set_ylabel('Average Rating', color=C_PRIMARY)
ax6a.set_title('Rating & Review Volume by Discount Bracket', fontweight='bold')
ax6a.set_xticks(x_pos)
ax6a.set_xticklabels(bracket_stats['discount_bracket'])
ax6a.set_ylim(3.5, 4.5)
ax6a2 = ax6a.twinx()
ax6a2.bar(x_pos + width/2, bracket_stats['avg_rating_count'], width, color=C_ACCENT,
          alpha=0.75, label='Avg Review Count')
ax6a2.set_ylabel('Average Review Count', color=C_ACCENT)
lines1, labels1 = ax6a.get_legend_handles_labels()
lines2, labels2 = ax6a2.get_legend_handles_labels()
ax6a.legend(lines1 + lines2, labels1 + labels2, loc='upper left')
chart_discount_bracket = fig_to_b64(fig6)

# Chart 7: Price Segment Analysis
df_valid['price_segment'] = pd.cut(df_valid['actual_price_num'],
    bins=[0, 300, 600, 1000, 3000, float('inf')],
    labels=['Budget (<₹300)', 'Value (₹300-600)', 'Mid (₹600-1K)', 'Premium (₹1K-3K)', 'Luxury (>₹3K)'])
price_stats = df_valid.groupby('price_segment', observed=True).agg(
    count=('rating_num', 'count'),
    avg_rating=('rating_num', 'mean'),
    avg_discount=('discount_pct_num', 'mean')
).reset_index().dropna()

fig7, ax7 = plt.subplots(figsize=(9, 4.5))
x7 = np.arange(len(price_stats))
w7 = 0.35
ax7.bar(x7 - w7/2, price_stats['avg_rating'], w7, color=C_PRIMARY, alpha=0.85, label='Avg Rating')
ax7.set_ylabel('Average Rating')
ax7.set_title('Rating & Discount by Price Segment', fontweight='bold')
ax7.set_xticks(x7)
ax7.set_xticklabels(price_stats['price_segment'], fontsize=9)
ax7.set_ylim(3.0, 4.8)
ax7r = ax7.twinx()
ax7r.bar(x7 + w7/2, price_stats['avg_discount'], w7, color=C_ACCENT, alpha=0.75, label='Avg Discount %')
ax7r.set_ylabel('Average Discount %')
l1, lab1 = ax7.get_legend_handles_labels()
l2, lab2 = ax7r.get_legend_handles_labels()
ax7.legend(l1 + l2, lab1 + lab2, loc='upper right')
chart_price_segment = fig_to_b64(fig7)

# Chart 8: Rating Count Distribution (log scale)
fig8, ax8 = plt.subplots(figsize=(8, 4))
log_counts = np.log10(df_valid['rating_count_num'].dropna().clip(lower=1))
ax8.hist(log_counts, bins=40, color=C_PRIMARY, alpha=0.85, edgecolor='white')
ax8.axvline(np.log10(median_rating_cnt), color=C_ACCENT, linestyle='--', linewidth=2,
           label=f'Median: {median_rating_cnt:,.0f}')
ax8.set_title('Distribution of Review Counts (Log Scale)', fontweight='bold')
ax8.set_xlabel('Log10(Review Count)')
ax8.set_ylabel('Number of Products')
ax8.legend()
chart_review_dist = fig_to_b64(fig8)

# Chart 9: Top 10 Categories by Volume Treemap-style horizontal bar
fig9, ax9 = plt.subplots(figsize=(9, 5))
top_cats_vol = top_cats.sort_values('count', ascending=True).tail(10)
colors9 = plt.cm.Blues(np.linspace(0.4, 0.9, len(top_cats_vol)))
ax9.barh(top_cats_vol['top_category'], top_cats_vol['count'], color=colors9, edgecolor='white', height=0.7)
for i, (cat, cnt) in enumerate(zip(top_cats_vol['top_category'], top_cats_vol['count'])):
    ax9.text(cnt + 1, i, f'{cnt:,}', va='center', fontsize=9)
ax9.set_title('Product Count by Top Category', fontweight='bold')
ax9.set_xlabel('Number of Products')
chart_cat_volume = fig_to_b64(fig9)

# Chart 10: Rating vs Review Count scatter
fig10, ax10 = plt.subplots(figsize=(8, 5))
ax10.scatter(df_valid['rating_num'], df_valid['rating_count_num'], alpha=0.3, s=15,
            c=C_ACCENT, edgecolors='none')
ax10.set_yscale('log')
ax10.set_title('Rating vs Review Count (Engagement)', fontweight='bold')
ax10.set_xlabel('Rating')
ax10.set_ylabel('Review Count (log scale)')
ax10.axhline(median_rating_cnt, color=C_DARK, linewidth=1, linestyle=':', alpha=0.5)
chart_rating_vs_reviews = fig_to_b64(fig10)

print("  All charts generated.")

# ── Category rankings ──────────────────────────────────────────────────────
cat_agg = df_valid.groupby('top_category').agg(
    product_count=('rating_num', 'count'),
    avg_rating=('rating_num', 'mean'),
    avg_discount=('discount_pct_num', 'mean'),
    avg_rating_count=('rating_count_num', 'mean'),
    avg_price=('discounted_price_num', 'median')
).reset_index()

best_rating = cat_agg.nlargest(5, 'avg_rating')[['top_category', 'avg_rating', 'product_count']]
worst_rating = cat_agg.nsmallest(5, 'avg_rating')[['top_category', 'avg_rating', 'product_count']]
best_engagement = cat_agg.nlargest(5, 'avg_rating_count')[['top_category', 'avg_rating_count', 'product_count']]

# ── High engagement products ───────────────────────────────────────────────
high_eng = df_valid.nlargest(20, 'rating_count_num')[
    ['product_name', 'top_category', 'rating_num', 'rating_count_num', 'discounted_price_num', 'discount_pct_num']
].copy()
high_eng.columns = ['Product', 'Category', 'Rating', 'Reviews', 'Price (INR)', 'Discount %']
high_eng['Rating'] = high_eng['Rating'].round(2)
high_eng['Discount %'] = high_eng['Discount %'].round(1)
high_eng['Price (INR)'] = high_eng['Price (INR)'].round(0).astype(int)

# ── Sentiment: word frequency from review titles ───────────────────────────
print("Analyzing review sentiment...")
positive_words = {'good','great','excellent','best','nice','worth','value','awesome','amazing',
                  'perfect','super','love','fast','quality','durable','working','satisfied','wonderful',
                  'happy','impressive','recommend','decent','useful','sturdy','reliable','premium',
                  'comfortable','easy'}
negative_words = {'bad','poor','waste','worst','worse','useless','defective','broken','cheap',
                  'disappointed','not working','terrible','horrible','damaged','issue','problem',
                  'fake','returned','refund','pathetic','useless','flimsy','slow','overheating'}

all_titles = df['review_title'].dropna().str.lower().str.split(',').explode().str.strip()
all_titles = all_titles[all_titles.str.len() > 0]

pos_freq = Counter()
neg_freq = Counter()
for title in all_titles:
    words = set(title.split())
    for w in words:
        w_clean = w.strip('.,!?():;""\'')
        if w_clean in positive_words:
            pos_freq[w_clean] += 1
        if w_clean in negative_words:
            neg_freq[w_clean] += 1

top_pos = pos_freq.most_common(10)
top_neg = neg_freq.most_common(10)

# ── Build HTML Report ──────────────────────────────────────────────────────
print("Building HTML report...")

def number_fmt(n, decimals=1):
    if pd.isna(n):
        return 'N/A'
    if decimals == 0:
