def clean_price(val):
    """Clean price strings like '₹399' or '₹1,099' to float."""
    if pd.isna(val):
        return np.nan
    s = str(val).replace('₹', '').replace(',', '').strip()
    try:
        return float(s)
    except ValueError:
        return np.nan

def clean_pct(val):
    """Clean percentage strings like '64%' to float."""
    if pd.isna(val):
        return np.nan
    try:
        return float(str(val).replace('%', '').strip())
    except ValueError:
        return np.nan

def clean_rating(val):
    """Clean rating - handle pipe-separated malformed values."""
    if pd.isna(val):
        return np.nan
    s = str(val).strip()
    if '|' in s:
        parts = [float(p) for p in re.split(r'\|+', s) if p.strip()]
        return np.mean(parts) if parts else np.nan
    try:
        return float(s)
    except ValueError:
        return np.nan

def clean_int(val):
    """Clean integer strings with commas like '24,269'."""
    if pd.isna(val):
        return np.nan
    s = str(val).replace(',', '').strip()
    try:
        return int(s)
    except ValueError:
        return np.nan

print("Cleaning data...")
df['discounted_price_num'] = df['discounted_price'].apply(clean_price)
df['actual_price_num']     = df['actual_price'].apply(clean_price)
df['discount_pct_num']     = df['discount_percentage'].apply(clean_pct)
df['rating_num']           = df['rating'].apply(clean_rating)
df['rating_count_num']     = df['rating_count'].apply(clean_int)

# Compute savings amount
df['savings_amount'] = df['actual_price_num'] - df['discounted_price_num']
df['savings_pct_check'] = (df['savings_amount'] / df['actual_price_num'] * 100)

# Extract top-level category
def top_category(cat):
    if pd.isna(cat):
        return 'Unknown'
    return str(cat).split('|')[0].strip()

df['top_category'] = df['category'].apply(top_category)

# Extract sub-category (second level)
def sub_category(cat):
    if pd.isna(cat):
        return 'Unknown'
    parts = str(cat).split('|')
    if len(parts) >= 2:
        return parts[1].strip()
    return parts[0].strip()

df['sub_category'] = df['category'].apply(sub_category)

